{
  "title": "The Mirror Rescue of the Broken City",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map of the ruined royal city.",
      "visual_description": "A windswept hilltop overlook at dusk; an ink-stained coat flares as a brass compass spins; the shattered skyline of the royal city glows below with cracked towers and torn banners.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp sparks awake with a warning.",
      "visual_description": "Close-up of an oil lamp held aloft, a single glowing eye blinking inside its flame, casting long orange shadows across Mara's tired face.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scouts the broken outer wall.",
      "visual_description": "A small clockwork fox with blue glass eyes perches on rubble at the city's edge, key-wind tail ticking, ears angled toward distant torchlight.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The glass diver emerges from a cracked window.",
      "visual_description": "A figure in a clear diving helmet steps out of a tall shattered window as if from water; coat panels reflect broken city lights in jagged shards.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "They approach the great castle gates.",
      "visual_description": "Enormous iron gates hang half-open, scorched and bent; torn royal banners flap above; the four travelers pause in the gate's deep shadow.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "The lamp warns of a cursed tower ahead.",
      "visual_description": "A leaning tower wrapped in violet mist looms over a courtyard; the oracle lamp's flame-eye narrows, projecting a beam of warning runes onto cracked flagstones.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Tin Fox finds a sleeping official slumped at a checkpoint.",
      "visual_description": "A wooden booth in a ruined plaza; the sleeping tax collector slumps over a ledger pillow, stamped papers stuck to his sleeves, snoring as the clockwork fox sniffs his boots.",
      "characters": ["tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 8,
      "caption": "Mara tries to question the dozing official.",
      "visual_description": "Mara crouches beside the slumped tax collector, shaking his shoulder; he mumbles, a stamp falling from his hand onto her compass.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Distant roars echo from a smoking tower.",
      "visual_description": "Behind broken rooftops, a far tower belches green smoke and a long shadow uncoils across the clouds; the team ducks behind a fallen statue.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "An armored patrol marches past their hiding spot.",
      "visual_description": "Steel boots and tall pikes pass within inches of the hidden party; Tin Fox holds perfectly still as lantern light sweeps over the rubble.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "The glass diver slips into a tall mirror.",
      "visual_description": "Inside a ransacked hall of mirrors, the diver leans forward and sinks shoulder-first into a silver pane, ripples spreading like water; the others watch the surface still.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "Behind the mirror, the captive waits in a locked room.",
      "visual_description": "A dim cell of polished glass walls; the glass diver kneels beside the sleeping tax collector's twin ledger, finding their true target chained beside a glowing magic door.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 13,
      "caption": "Oracle lamp reads the magic door's riddle.",
      "visual_description": "A heavy door covered in shifting silver glyphs; the oracle lamp hovers close, its flame-eye reflecting the runes back in correct order.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "Tin Fox triggers the lock with a precise tail-wind.",
      "visual_description": "The clockwork fox stretches up on hind legs; its key-wind tail clicks into a brass slot; gears in the magic door spin and unlatch with a flash of blue light.",
      "characters": ["tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "They drag the dozing official back through the mirror.",
      "visual_description": "The glass diver and Mara haul the snoring tax collector through a rippling pane; papers flutter, ink smears, the lamp lighting the way back.",
      "characters": ["glass_diver", "mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "Frightened figures point them toward the bridge.",
      "visual_description": "In a narrow alley lit by Mara's lamp, frightened townsfolk shadows shrink into doorways while pointing pale hands toward a far stone bridge; only our party stands in full light.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "Armored patrols charge as the team races onto the bridge.",
      "visual_description": "An old stone bridge over a black river; torches and pike-tips swarm from the far gate; the party sprints across, Tin Fox skidding, the lamp swinging wildly.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "Beyond the bridge, the ruined city falls behind.",
      "visual_description": "Dawn breaks over open country; the broken skyline shrinks at the horizon; Mara folds her map, the diver's coat dims, Tin Fox sits upright, the lamp blinks slowly, and the tax collector dozes on a tree stump.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

